  "a_sentences": [
    {
      "a_text": "Das kantonale Gericht hat die Bestimmungen und Grundsätze zu den am 1. Januar 2022 revidierten Bestimmungen im IVG, zur Invalidität nach Art. 8 Abs. 1 ATSG in Verbindung mit Art. 4 Abs. 1 IVG, zur Erwerbsunfähigkeit nach Art. 7 ATSG und zum Rentenanspruch nach Art. 28 IVG sowie die Revisionsregeln nach Art. 17 Abs. 1 ATSG und die Rechtsprechung zum Beweiswert medizinischer Berichte und Gutachten korrekt dargelegt.",
      "b_propositions": ["P1", "P2", "P3"]
    },
    {
      "a_text": "Die Vorinstanz war nicht verpflichtet, sich mit jeder einzelnen Rüge des Versicherten einlässlich auseinanderzusetzen.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Eine eigenständige Prüfung der Indikatoren durch den Versicherten erübrigte sich, da keine psychische Störung mit Auswirkung auf die Arbeitsfähigkeit vorliegt.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt, dass die Vorinstanz kein Bundesrecht verletzt hat, indem sie dem ABI-Gutachten vom 28. November 2023 vollen Beweiswert zuerkannte und gestützt darauf von einer 80%igen Arbeitsfähigkeit des Versicherten ausging.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Die Vorinstanz verneinte Eingliederungsmassnahmen zu Recht, da die Voraussetzungen nach Art. 8 Abs. 1 lit. a IVG nicht erfüllt sind.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Der Versicherte vermag mit seinen Vorbringen kein bundesrechtswidriges Vorgehen der Vorinstanz aufzuzeigen.",
      "b_propositions": ["P7"]
    }
  ]
}
